package ch.bbw.zork;/** * Author:  Michael Kolling, Version: 1.1, Date: August 2000 * refactoring: Rinaldo Lanza, September 2020 */import java.util.ArrayList;import java.util.HashMap;import java.util.List;public class Room {		private String description;	private HashMap<String, Room> exits;	private int coins;	private List<Item> items;	private boolean locked;	public Room(String description) {		this.description = description;		this.exits = new HashMap<>();		this.coins = 0;		this.items = new ArrayList<>();		this.locked = false;	}	public Room(String description, int coins) {		this(description);		this.coins = Math.max(0, coins);	}	public boolean isLocked() {		return locked;	}	public void lock() {		locked = true;	}	public void unlock() {		locked = false;	}	public void addItem(Item item) {		if (item != null) {			items.add(item);		}	}	public List<Item> collectItems() {		List<Item> collectedItems = new ArrayList<>(items);		items.clear();		return collectedItems;	}	public int collectCoins() {		int collectedCoins = coins;		coins = 0;		return collectedCoins;	}	public void setExit(String direction, Room room) {		if (direction != null && room != null) {			exits.put(direction, room);		}	}	public String shortDescription() {		return description;	}	public String longDescription() {		StringBuilder stringBuilder = new StringBuilder("You are in " + description + ".\n");		stringBuilder.append(exitString());		return stringBuilder.toString();	}	private String exitString() {		return "Exits: " + String.join(" ", exits.keySet());	}	public Room nextRoom(String direction) {		return exits.get(direction);	}}